S={(0,0),(1,1),(1,2),(2,0),(2,1)}
K={(0,1),(1,1),(1,2),(2,0),(2,2)}
def rot(p): return {(x,y) for x,y in [(2-c,r) for r,c in p]}
def refl(p): return {(r,2-c) for r,c in p}
for x in [S,rot(S),rot(rot(S)),rot(rot(rot(S))),refl(S),rot(refl(S)),rot(rot(refl(S))),rot(rot(rot(refl(S))) )]: print(sorted(x),x==K)
